int cfw_scene_message(customCfwContext *ctx, const uint8_t *msg, uint32_t len,
                      uint8_t *status, uint16_t *request);
void cfw_scene_reset(customCfwContext *ctx, uint8_t cap);
void cfw_scene_render(customCfwContext *ctx);
void cfw_scene_hide(customCfwContext *ctx);

/* page.c */
int cfw_page_open(customCfwContext *ctx, uint8_t *reason);
void cfw_page_close(customCfwContext *ctx, uint8_t reason);
void cfw_page_ensure_ui(customCfwContext *ctx);
void cfw_page_tick(customCfwContext *ctx);

/* input.c */
void cfw_input_attach(customCfwContext *ctx, void *root);
void cfw_gesture(customCfwContext *ctx, uint8_t type, uint8_t source);

/* ident.c */
void cfw_send_ident(customCfwContext *ctx);
void cfw_send_page_state(customCfwContext *ctx, uint8_t state, uint8_t reason);

/* link.c */
int cfw_uplink_push(customCfwContext *ctx, const uint8_t *data, uint8_t len);
void cfw_uplink_flush(customCfwContext *ctx);
void cfw_control(customCfwContext *ctx, uint8_t ctrl);
void cfw_feed_records(customCfwContext *ctx, const uint8_t *data, uint32_t len);

/* ---- the one-and-only TIONativeMessage ABI (from the stock file bridge) ---- */
#define TIO_MSG_ID 0x54494d47u     /* 'TIMG' */
typedef struct {
    uint32_t id;
    const uint8_t *data;
    uint32_t bytes, reserved;
    void *context;
    uint8_t mode, padding[3];
} TIONativeMessage;

typedef struct {
    const uint8_t *data;
    uint32_t declared;
    char filename[256];
    char uuid[64];
    uint8_t route, complete, reserved[2];
    uint32_t received;
} TIONativeFile;

#endif /* GLASSLY_CFW_H */
